package saver

import (
	"context"
	"testing"
)

type gsrWitnessStore struct {
	calls int
}

func (s *gsrWitnessStore) Put(ctx context.Context, key, value string) error {
	s.calls++
	if err := ctx.Err(); err != nil {
		return err
	}
	return nil
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	store := &gsrWitnessStore{}
	_ = Save(ctx, store, "test-id", "part-a", "part-b")

	if store.calls >= 2 {
		t.Fatalf("Save with cancelled context made %d Store.Put calls, want < 2", store.calls)
	}
}

package saver

import (
	"context"
	"testing"
)

type gsrWitnessStore struct {
	calls int
}

func (s *gsrWitnessStore) Put(ctx context.Context, key, value string) error {
	s.calls++
	if ctx.Err() != nil {
		return ctx.Err()
	}
	return nil
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	store := &gsrWitnessStore{}
	err := Save(ctx, store, "id", "a", "b")

	if store.calls != 1 {
		t.Fatalf("store.calls = %v, want %v", store.calls, 1)
	}
	if err != context.Canceled {
		t.Fatalf("err = %v, want %v", err, context.Canceled)
	}
}

