import (
	"context"
	"testing"
)

type gsrWitnessStore struct {
	calledB bool
}

func (s *gsrWitnessStore) Put(ctx context.Context, key, value string) error {
	if key == "test/b" {
		s.calledB = true
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	return nil
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	s := &gsrWitnessStore{}
	_ = Save(ctx, s, "test", "a", "b")

	if s.calledB {
		t.Fatalf("s.calledB = %v, want %v", s.calledB, false)
	}
}

package poll

import (
	"context"
	"testing"
)

type gsrFakeSource struct {
	calls int
}

func (s *gsrFakeSource) Get(ctx context.Context, key string) (string, error) {
	s.calls++
	if err := ctx.Err(); err != nil {
		return "", err
	}
	return "", ErrNotReady
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	src := &gsrFakeSource{}
	_, _ = Poll(ctx, src, "test")

	if src.calls != 1 {
		t.Fatalf("Poll with cancelled context made %d calls to Get, want 1", src.calls)
	}
}

