package upload

import (
	"errors"
	"testing"
)

type gsrWitnessFailWriter struct {
	flushed bool
}

func (f *gsrWitnessFailWriter) Write(part string) error {
	return errors.New("write error")
}

func (f *gsrWitnessFailWriter) Flush() error {
	f.flushed = true
	return nil
}

func TestGSRWitness(t *testing.T) {
	w := &gsrWitnessFailWriter{}
	_ = Upload(w, []string{"a"})
	if w.flushed {
