package memo

import "testing"

func TestGSRWitness(t *testing.T) {
	c := New()
	if c == nil {
		t.Skip("gsr-setup: New() returned nil")
	}
	calls := 0
	load := func(key string) (string, error) {
		calls++
		return "value", nil
	}

	_, err := c.Get("k", load)
	if err != nil {
		t.Skip("gsr-setup: first Get returned unexpected error:", err)
	}
	_, err = c.Get("k", load)
	if err != nil {
		t.Skip("gsr-setup: second Get returned unexpected error:", err)
	}

	if calls != 1 {
		t.Fatalf("load called %d times, want 1", calls)
	}
}

